let boxed=new String('cat'),again=Object(boxed),from=Object('cat');
test.record(typeof boxed);test.record(boxed instanceof String);test.record(again===boxed);test.record(from!==boxed);
test.record(Object.getPrototypeOf(boxed)===String.prototype);test.record(Object.prototype.toString.call(boxed));
test.record(String.prototype.valueOf.call(boxed));test.record(String.prototype.toString.call(boxed));
test.record(new String().valueOf());test.record(new String(undefined).valueOf());test.record(new String(null).valueOf());
'ok';

let boxed=new String('a\u00f1');
for(let key of ['0','1','length']){let d=Object.getOwnPropertyDescriptor(boxed,key);test.record([d.value,d.writable,d.enumerable,d.configurable].join('|'));}
test.record(Object.getOwnPropertyDescriptor(boxed,'2'));test.record(boxed[0]);test.record(boxed.length);
'ok';

let boxed=new String('ab'),errors=[];
try{(function(){'use strict';boxed[0]='a';})();}catch(e){errors.push(e.name);}
try{(function(){'use strict';boxed.length=2;})();}catch(e){errors.push(e.name);}
try{(function(){'use strict';delete boxed[1];})();}catch(e){errors.push(e.name);}
try{(function(){'use strict';delete boxed.length;})();}catch(e){errors.push(e.name);}
test.record(errors.join('|'));test.record(boxed.valueOf());
'ok';

function loose(){return [typeof this,this instanceof String,this.valueOf()].join('|');}function strict(){'use strict';return typeof this;}
test.record(loose.call('abc'));test.record(strict.call('abc'));test.record(Object.getPrototypeOf(Object(''))===String.prototype);
'ok';

let log='',holder={_x:0,get x(){log+='g';return this._x;},set x(v){log+='s';this._x=v;}},key={toString:function(){log+='k';return 'x';}};function receiver(){log+='b';return holder;}function rhs(){log+='r';return 3;}
test.record(receiver()[key]||=rhs());test.record(log);log='';test.record(receiver()[key]||=rhs());test.record(log);log='';test.record(receiver()[key]&&=rhs());test.record(log);
