let marker={},log='',a={get x(){log+='g';throw marker;},set x(v){log+='s';}},b={get x(){log+='G';return 0;},set x(v){log+='S';throw marker;}};
try{a.x||=(log+='r',2);}catch(e){test.record(e===marker);}test.record(log);log='';
try{b.x||=(log+='R',2);}catch(e){test.record(e===marker);}test.record(log);log='';
try{b.x||=(function(){log+='r';throw marker;})();}catch(e){test.record(e===marker);}test.record(log);
'ok';

let log='',holder={get x(){log+='g';return {valueOf:function(){log+='l';return 3;}};},set x(v){log+='s';test.record(v);}},key={toString:function(){log+='k';return 'x';}};
function receiver(){log+='b';return holder;}function rhs(){log+='r';return {valueOf:function(){log+='e';return 2;}};}
test.record(receiver()[key]**=rhs());test.record(log);
'ok';

